window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-d81cd472a47abcaa"]={"versions": [{"id": "FIG-d81cd472a47abcaa", "releases": ["R4.2.2", "R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Objektdiagramm (Instanzebene) zur Veranschaulichung des AUTOSAR-Metamodells im Kontext des Modell- und Datenaustauschs zwischen Werkzeugen (AUTOSAR Interoperability of Tools). Dargestellt ist eine Paketierungsstruktur nach dem Verschieben eines Modellelements in ein anderes ARPackage.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Instanzen und deren Beziehungen:</p>\n<ul class=\"fig-list\">\n<li><code>:ARPackage</code> mit Attribut <code>shortName = OEM</code> aggregiert per Komposition (<code>+element</code>) die Instanz <code>:ApplicationPrimitiveDataType</code>.</li>\n<li><code>:ApplicationPrimitiveDataType</code> mit <code>shortName = velocityType</code> enthält per Komposition:</li>\n<li><code>+invalidValue</code>: Instanz <code>:NumericalValueSpecification</code> mit Attribut <code>value = 10000</code>.</li>\n<li><code>+displayFormat</code>: Instanz <code>:DisplayFormatString</code> mit Attribut <code>value = %f6.2</code>.</li>\n<li><code>:ARPackage</code> mit Attribut <code>shortName = supplier</code> aggregiert per Komposition (<code>+elements</code>) die Instanz <code>:SenderReceiverInterface</code>.</li>\n<li><code>:SenderReceiverInterface</code> mit Attributen <code>isService = false</code> und <code>shortName = interface</code> aggregiert per Komposition (<code>+dataElement</code>) die Instanz <code>:VariableDataPrototype</code>.</li>\n<li><code>:VariableDataPrototype</code> mit Attribut <code>shortName = velocity</code> referenziert über die gerichtete Assoziation <code>+type</code> den Datentyp <code>:ApplicationPrimitiveDataType</code> (<code>shortName = velocityType</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Objektdiagramm ohne Verhaltens- oder Sequenzdarstellung. Die Abbildung zeigt den resultierenden Modellzustand nach einer Verschiebe-Operation (Move-Operation) eines Modellelements über Paketgrenzen hinweg.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Veranschaulicht die Auswirkungen des Verschiebens eines Modellelements (<code>SenderReceiverInterface</code> nach <code>supplier</code>):</p>\n<ul class=\"fig-list\">\n<li>Bei Verschiebung eines Modellelements in ein anderes <code>ARPackage</code> ändern sich die Elementlisten des Quell- und Zielpakets.</li>\n<li>Werkzeuge müssen berücksichtigen, dass absolute Referenzen (Short-Name-Pfade wie <code>/supplier/interface</code>) auf das verschobene Element angepasst werden müssen, da AUTOSAR zur Adressierung von Modellelementen standardmäßig absolute Pfade verwendet.</li>\n<li>Paketexterne Referenzen wie die Typ-Referenz (<code>+type</code>) vom Prototyp innerhalb der Schnittstelle auf den Datentyp im OEM-Paket (<code>/OEM/velocityType</code>) bleiben als quellenübergreifende Pfade bestehen.</li>\n</ul>"}, {"id": "FIG-a0c42bc79f6c7a1f", "releases": ["R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Objektdiagramm (Instanzebene) zur Veranschaulichung des AUTOSAR-Metamodells im Kontext des Modell- und Datenaustauschs zwischen Werkzeugen (AUTOSAR Interoperability of Tools). Dargestellt ist eine Paketierungsstruktur nach dem Verschieben eines Modellelements in ein anderes ARPackage.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Instanzen und deren Beziehungen:</p>\n<ul class=\"fig-list\">\n<li><code>:ARPackage</code> mit Attribut <code>shortName = OEM</code> aggregiert per Komposition (<code>+element</code>) die Instanz <code>:ApplicationPrimitiveDataType</code>.</li>\n<li><code>:ApplicationPrimitiveDataType</code> mit <code>shortName = velocityType</code> enthält per Komposition:</li>\n<li><code>+invalidValue</code>: Instanz <code>:NumericalValueSpecification</code> mit Attribut <code>value = 10000</code>.</li>\n<li><code>+displayFormat</code>: Instanz <code>:DisplayFormatString</code> mit Attribut <code>value = %f6.2</code>.</li>\n<li><code>:ARPackage</code> mit Attribut <code>shortName = supplier</code> aggregiert per Komposition (<code>+elements</code>) die Instanz <code>:SenderReceiverInterface</code>.</li>\n<li><code>:SenderReceiverInterface</code> mit Attributen <code>isService = false</code> und <code>shortName = interface</code> aggregiert per Komposition (<code>+dataElement</code>) die Instanz <code>:VariableDataPrototype</code>.</li>\n<li><code>:VariableDataPrototype</code> mit Attribut <code>shortName = velocity</code> referenziert über die gerichtete Assoziation <code>+type</code> den Datentyp <code>:ApplicationPrimitiveDataType</code> (<code>shortName = velocityType</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Objektdiagramm ohne Verhaltens- oder Sequenzdarstellung. Die Abbildung zeigt den resultierenden Modellzustand nach einer Verschiebe-Operation (Move-Operation) eines Modellelements über Paketgrenzen hinweg.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Veranschaulicht die Auswirkungen des Verschiebens eines Modellelements (<code>SenderReceiverInterface</code> nach <code>supplier</code>):</p>\n<ul class=\"fig-list\">\n<li>Bei Verschiebung eines Modellelements in ein anderes <code>ARPackage</code> ändern sich die Elementlisten des Quell- und Zielpakets.</li>\n<li>Werkzeuge müssen berücksichtigen, dass absolute Referenzen (Short-Name-Pfade wie <code>/supplier/interface</code>) auf das verschobene Element angepasst werden müssen, da AUTOSAR zur Adressierung von Modellelementen standardmäßig absolute Pfade verwendet.</li>\n<li>Paketexterne Referenzen wie die Typ-Referenz (<code>+type</code>) vom Prototyp innerhalb der Schnittstelle auf den Datentyp im OEM-Paket (<code>/OEM/velocityType</code>) bleiben als quellenübergreifende Pfade bestehen.</li>\n</ul>"}], "trans": [{"from": "FIG-d81cd472a47abcaa", "to": "FIG-a0c42bc79f6c7a1f", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
